package local.tvmorph.tv;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.net.wifi.WifiManager;import java.util.concurrent.*;import java.net.*;import org.json.*;
/** Isolated local-network view. The launcher and IPTV keep their own lifecycles. */
public class NetworkActivity extends Activity {
 WebView web;final ExecutorService io=Executors.newFixedThreadPool(2),discovery=Executors.newSingleThreadExecutor();final LanSsdp ssdp=new LanSsdp();volatile boolean dead;final java.util.concurrent.atomic.AtomicBoolean scanning=new java.util.concurrent.atomic.AtomicBoolean();final java.util.concurrent.Semaphore slots=new java.util.concurrent.Semaphore(8);WifiManager.MulticastLock lock;
 public void onCreate(Bundle b){super.onCreate(b);NetworkOwner.current=this;web=new WebView(this);web.setVisibility(android.view.View.INVISIBLE);setContentView(web);PageFirstFrame.awaitVisible(this,web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setTextZoom(100);s.setUseWideViewPort(true);s.setLoadWithOverviewMode(true);s.setSupportZoom(false);web.setBackgroundColor(0xff101c35);web.addJavascriptInterface(new Bridge(),"NetworkNative");web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){v.postVisualStateCallback(1,new WebView.VisualStateCallback(){@Override public void onComplete(long requestId){if(!dead)v.setVisibility(android.view.View.VISIBLE);}});}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}public void onReceivedSslError(WebView v,SslErrorHandler h,android.net.http.SslError e){h.cancel();}});web.loadUrl("file:///android_asset/tv/network/index.html");}
 void cancel(){ssdp.cancel();LanHttpClient.cancel(this);releaseMulticast();}
 void releaseMulticast(){if(lock!=null){try{if(lock.isHeld())lock.release();}catch(Exception ignored){}lock=null;}}
 protected void onResume(){super.onResume();if(web!=null)web.evaluateJavascript("window.dispatchEvent(new Event('networkResume'))",null);}
 protected void onPause(){cancel();if(web!=null)web.evaluateJavascript("window.dispatchEvent(new Event('networkSuspend'))",null);super.onPause();}
 protected void onDestroy(){dead=true;if(NetworkOwner.current==this)NetworkOwner.current=null;cancel();io.shutdownNow();discovery.shutdownNow();if(web!=null){web.removeJavascriptInterface("NetworkNative");web.destroy();web=null;}super.onDestroy();}
 @Override public void finish(){super.finish();overridePendingTransition(0,0);}
 public void onBackPressed(){if(web!=null)web.evaluateJavascript("window.NetworkUI&&NetworkUI.back()",r->{if(!"true".equals(r))finish();});else finish();}
 void result(String id,boolean ok,Object value){String payload=value instanceof JSONObject||value instanceof JSONArray?value.toString():JSONObject.quote(String.valueOf(value));if(payload.length()>250000){ok=false;payload=JSONObject.quote("Device response too large for this screen. Use a smaller server page/photo.");}final String encoded=payload;final boolean success=ok;runOnUiThread(()->{if(!dead&&web!=null)try{web.evaluateJavascript("window.networkResult("+JSONObject.quote(id)+","+success+","+encoded+")",null);}catch(RuntimeException oversized){web.evaluateJavascript("window.networkResult("+JSONObject.quote(id)+",false,\"Could not display device response.\")",null);}});}
 public final class Bridge {
  @JavascriptInterface public boolean isTelevision(){android.app.UiModeManager mode=(android.app.UiModeManager)getSystemService(UI_MODE_SERVICE);return getPackageName().equals("local.tvmorph.tv")||mode!=null&&mode.getCurrentModeType()==android.content.res.Configuration.UI_MODE_TYPE_TELEVISION;}
  @JavascriptInterface public void showKeyboard(String id,String value){if(!java.util.Arrays.asList("net-url","net-name","net-streambase","net-user","net-password").contains(id))return;runOnUiThread(()->{if(web==null)return;web.requestFocus();web.evaluateJavascript("document.getElementById("+JSONObject.quote(id)+").focus()",r->{android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(keyboard!=null&&web!=null)keyboard.showSoftInput(web,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});});}
  @JavascriptInterface public String settingsJson(){try{return UiSettings.get(NetworkActivity.this).put("phoneAppearance",getSharedPreferences("cleartv",MODE_PRIVATE).getString("appearance","light")).toString();}catch(Exception e){return "{}";}}
  @JavascriptInterface public String capabilities(){return "{\"discovery\":true,\"transport\":true,\"credentials\":true,\"playback\":\"Android native HTTP/HLS; codecs device-dependent\",\"rtsp\":false}";}
  @JavascriptInterface public void exit(){runOnUiThread(()->finish());}
  @JavascriptInterface public void cancel(){NetworkActivity.this.cancel();}
  @JavascriptInterface public void request(String id,String action,String text){if(dead||text==null||text.length()>131072||id.length()>80)return;if(!slots.tryAcquire()){result(id,false,"Network is busy. Retry shortly.");return;}if(action.equals("scan")){if(!scanning.compareAndSet(false,true)){slots.release();result(id,false,"A scan is already running.");return;}ssdp.cancelled=false;}ExecutorService queue=action.equals("scan")?discovery:io;try{queue.execute(()->{try{JSONObject p=new JSONObject(text);Object value;
   if(action.equals("scan")){WifiManager wifi=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);if(wifi!=null){lock=wifi.createMulticastLock("MorphTV local SSDP");lock.setReferenceCounted(false);lock.acquire();}try{value=new JSONObject().put("items",ssdp.scan());}finally{releaseMulticast();}}
   else if(action.equals("credentials")){URI u=LanPolicy.validate(p.getString("url"));LanVault.save(NetworkActivity.this,LanPolicy.origin(u),p.optString("username"),p.optString("password"));value=new JSONObject().put("saved",true);}
   else if(action.equals("forget")){URI u=LanPolicy.validate(p.getString("url"));LanVault.remove(NetworkActivity.this,LanPolicy.origin(u));value=new JSONObject().put("removed",true);}
   else if(action.equals("fetch")){String method=p.optString("method","GET"),body=p.optString("body"),soap=p.optString("soap");if(!method.equals("GET")&&!(method.equals("POST")&&soap.matches("\"urn:schemas-upnp-org:service:ContentDirectory:[1-9][0-9]*#Browse\"")))throw new Exception("Only media browsing requests are allowed.");LanHttpClient.Reply reply=LanHttpClient.request(NetworkActivity.this,p.getString("url"),method,body,soap,p.optBoolean("probe"));value=new JSONObject().put("text",p.optBoolean("probe")?"":new String(reply.bytes,"UTF-8")).put("type",reply.type).put("bytes",reply.bytes.length).put("host",reply.host);}
   else if(action.equals("photo")){LanHttpClient.Reply image=LanHttpClient.request(NetworkActivity.this,p.getString("url"),"GET","","",false);if(!image.type.matches("(?i)image/(jpeg|png|webp|gif)(;.*)?"))throw new Exception("Unsupported photo format.");value=new JSONObject().put("data","data:"+image.type.split(";")[0]+";base64,"+android.util.Base64.encodeToString(image.bytes,2));}
   else if(action.equals("play")){URI u=LanPolicy.validate(p.getString("url"));String name=p.optString("name","Network media").substring(0,Math.min(250,p.optString("name","Network media").length()));boolean live=p.optBoolean("live");String key="network:"+Integer.toHexString(u.toString().hashCode());Intent intent=new Intent(NetworkActivity.this,NetworkPlayerActivity.class).putExtra("url",u.toString()).putExtra("name",name).putExtra("live",live).putExtra("resumeKey",key).putExtra("networkOrigin",LanPolicy.origin(u)).putExtra("itemKind","network");runOnUiThread(()->startActivity(intent));value=new JSONObject().put("sent",true);}
   else throw new Exception("Unsupported network operation.");result(id,true,value);
  }catch(Exception e){String message=e.getMessage();if(message==null||message.contains("://")||message.length()>220)message="Local device request failed. Check connection, credentials and device support.";result(id,false,message);}finally{slots.release();if(action.equals("scan"))scanning.set(false);}});}catch(RejectedExecutionException ignored){slots.release();if(action.equals("scan"))scanning.set(false);result(id,false,"Network view is closed.");}}
 }
}
